const out = [];
const skipped = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    if (/html/i.test(p.name || '')) { skipped.push(p.name); continue; }
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase(),
      qa_type: 'spelling_and_grammar',
      qa_label: 'Typos',
      skipped_html: skipped.slice()
    }});
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: 'en',
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__',
        skipped_html: []
      }});
      first = false;
    }
  }
}
for (const o of out) { o.json.skipped_html = skipped; }
return out;

const NO_REPEAT_WORD = ['id','ms','fil','vi','th','ko','ja','zh','zh_cn','zh_tw'];
const LEGIT_TRIPLE = ['schifffahrt','rollladen','stilllegung','stillleben','brennnessel',
  'schneeeule','kaffeeersatz','kaffeeernte','betttuch','balletttanz','sauerstoffflasche',
  'fussballliga','nulllinie','volllast','helllicht','sperrrad','fetttropf',
  'flussschiff','kunststofffenster','sammelllinse','schlussstrich','stofffarbe','jaaaar'];

function legitTriple(low) {
  for (const w of LEGIT_TRIPLE) { if (low.indexOf(w) !== -1) { return true; } }
  return false;
}
function stripNoise(s) {
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\S+@\S+\.\S+/g, ' ')
    .replace(/\[%[^\]]*\]/g, ' ')
    .replace(/%\d+\$[a-zA-Z]/g, ' ')
    .replace(/%[sdioxfeguc@]/g, ' ')
    .replace(/\{\{[^}]*\}\}/g, ' ')
    .replace(/\{[^}]*\}/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/&[a-zA-Z]+;/g, ' ')
    .replace(/&#\d+;/g, ' ')
    .replace(/\$\w+/g, ' ')
    .replace(/:\w+:/g, ' ');
}
function tokenize(s) {
  const parts = String(s).split(/[^\p{L}\p{M}]+/u);
  const out = [];
  for (const p of parts) { if (p.length > 0) { out.push(p); } }
  return out;
}
function isAllUpper(t) { return t === t.toUpperCase() && /\p{L}/u.test(t); }
function isPseudo(iso) {
  const s = (iso || '').toLowerCase();
  return s === 'pst' || s.indexOf('pseudo') >= 0;
}
function findTypos(text, iso, srcSet) {
  const findings = [];
  const clean = stripNoise(text);
  for (const tok of tokenize(clean)) {
    const low = tok.toLowerCase();
    if (srcSet[low]) { continue; }
    if (tok.length >= 4 && !isAllUpper(tok) && !legitTriple(low) && /(\p{L})\1\1/u.test(tok)) {
      findings.push({ rule: 'triple_letter', token: tok });
      continue;
    }
    if (/\p{Script=Latin}/u.test(tok) && /\p{Script=Cyrillic}|\p{Script=Greek}/u.test(tok)) {
      findings.push({ rule: 'mixed_script', token: tok });
      continue;
    }
  }
  if (NO_REPEAT_WORD.indexOf(iso) === -1) {
    const m = clean.match(/(?<!\p{L})(\p{L}{2,})[ \u00A0]+\1(?!\p{L})/giu);
    if (m) { for (const hit of m) { findings.push({ rule: 'repeated_word', token: hit.replace(/\s+/g, ' ').trim() }); } }
  }
  return findings;
}
function keyName(k) {
  const n = k.key_name;
  if (typeof n === 'string') { return n; }
  if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android || String(k.key_id); }
  return String(k.key_id);
}

const reqs = $('Build Typo Requests').all();
const res = $input.all();
const rows = [];
const failed = [];
const truncated = [];
let skippedHtml = [];
let controlStatus = null;
let scanned = 0;
let flaggedKeys = 0;

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (meta.skipped_html && meta.skipped_html.length > skippedHtml.length) { skippedHtml = meta.skipped_html; }

  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  scanned++;
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }

  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  if (total > keys.length) { truncated.push(meta.project_name); }

  for (const k of keys) {
    if (k.is_archived) { continue; }
    flaggedKeys++;
    const trs = k.translations || [];
    const srcSet = {};
    let srcText = '';
    for (const tr of trs) {
      if ((tr.language_iso || '').toLowerCase() === meta.base_lang) {
        srcText = typeof tr.translation === 'string' ? tr.translation : '';
        for (const t of tokenize(stripNoise(srcText))) { srcSet[t.toLowerCase()] = 1; }
      }
    }
    for (const tr of trs) {
      const iso = (tr.language_iso || '').toLowerCase();
      if (iso === meta.base_lang) { continue; }
      if (isPseudo(iso)) { continue; }
      if (tr.is_untranslated) { continue; }
      const v = tr.translation;
      if (typeof v !== 'string' || v.length === 0) { continue; }
      const hits = findTypos(v, iso, srcSet);
      for (const h of hits) {
        rows.push({
          project: meta.project_name,
          project_id: meta.project_id,
          lang: iso,
          key: keyName(k),
          key_id: k.key_id,
          rule: h.rule,
          token: h.token,
          target: v.length > 300 ? v.slice(0, 300) + '…' : v,
          source: srcText.length > 300 ? srcText.slice(0, 300) + '…' : srcText,
          is_reviewed: tr.is_reviewed ? 1 : 0
        });
      }
    }
  }
}

const byProject = {};
const projIds = {};
const byRule = {};
for (const row of rows) {
  if (!byProject[row.project]) { byProject[row.project] = {}; }
  if (!byProject[row.project][row.lang]) { byProject[row.project][row.lang] = 0; }
  byProject[row.project][row.lang]++;
  projIds[row.project] = row.project_id;
  byRule[row.rule] = (byRule[row.rule] || 0) + 1;
}

const names = Object.keys(byProject);
names.sort(function (a, b) {
  return a.replace(/^[^A-Za-z0-9]+/, '').toLowerCase().localeCompare(b.replace(/^[^A-Za-z0-9]+/, '').toLowerCase());
});

let msg = '*Lokalise nightly QA — typos in target languages*\n\n';
msg += '*Total:* ' + rows.length + ' in ' + names.length + ' project(s)\n\n';
if (names.length === 0) {
  msg = '*Lokalise nightly QA — typos in target languages*\n\n:white_check_mark: No high-confidence typos found.\n';
} else {
  for (const n of names) {
    const label = String(n).replace(/[<>|]/g, ' ').trim();
    msg += '<https://app.lokalise.com/project/' + projIds[n] + '/|' + label + '>\n';
    const isos = Object.keys(byProject[n]);
    isos.sort();
    for (const iso of isos) { msg += '    • ' + iso + ': ' + byProject[n][iso] + '\n'; }
    msg += '\n';
  }
}
if (failed.length > 0) { msg += '\n:warning: could not read: ' + failed.join(', '); }
if (truncated.length > 0) { msg += '\n:warning: over 500 flagged keys, count is a floor: ' + truncated.join(', '); }
if (controlStatus !== 400) { msg += '\n:rotating_light: control probe returned ' + controlStatus + ' instead of 400 — treat these numbers as unverified.'; }

return [{ json: {
  typo_message: msg,
  typo_total: rows.length,
  projects_with_typos: names.length,
  projects_scanned: scanned,
  flagged_keys_examined: flaggedKeys,
  by_project: byProject,
  by_rule: byRule,
  skipped_html: skippedHtml,
  failed: failed,
  truncated: truncated,
  control_status: controlStatus,
  rows: rows
}}];

const MAX_PAGES = 30;
const PER = 500;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
const capped = [];
let controlStatus = null;
let scanned = 0;
let skippedHtml = [];

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (meta.skipped_html && meta.skipped_html.length > skippedHtml.length) { skippedHtml = meta.skipped_html; }

  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  scanned++;
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  if (total === 0) { continue; }

  let pages = Math.ceil(total / PER);
  if (pages > MAX_PAGES) { pages = MAX_PAGES; capped.push(meta.project_name); }
  for (let p = 1; p <= pages; p++) {
    out.push({ json: {
      project_id: meta.project_id,
      project_name: meta.project_name,
      base_lang: meta.base_lang,
      page: p,
      pages: pages,
      flagged_total: total
    }});
  }
}

for (const o of out) {
  o.json.scanned = scanned;
  o.json.failed = failed;
  o.json.capped = capped;
  o.json.control_status = controlStatus;
  o.json.skipped_html = skippedHtml;
}
if (out.length === 0) {
  out.push({ json: { project_id: null, project_name: null, base_lang: 'en', page: 0, pages: 0, flagged_total: 0, scanned: scanned, failed: failed, capped: capped, control_status: controlStatus, skipped_html: skippedHtml } });
}
return out;
